
import com.sap.gateway.ip.core.customdev.util.Message
import javax.activation.DataHandler
import javax.mail.util.ByteArrayDataSource
import java.util.Base64

def Message processData(Message message) {

   def base64Parts = [
'''''',
'''''',
'''''',
]
String base64 = base64Parts.join('')

    // STEP 3: Decode Base64 into image bytes
    byte[] imageBytes = Base64.decoder.decode(base64.trim())

    // STEP 4: Create JPEG data source
    def dataSource = new ByteArrayDataSource(
        imageBytes,
        "image/jpeg"
    )

    // STEP 5: Create email attachment
    def dataHandler = new DataHandler(dataSource)

    // STEP 6: Add attachment to CPI message
    Map<String, DataHandler> attachments = [:]

    attachments.put(
        "saikomal_amount.jpeg",
        dataHandler
    )

    message.setAttachments(attachments)

    // STEP 7: Set email body
    message.setBody(
        "Please find the JPEG image attached."
    )

    return message
}
